-- VONG QUAY GOP HU (19/10/2026, chu game bao: nut "Đồng ý" khong lam gi + "sao gioi han xu cao vay?").
-- Idempotent, MariaDB 10.3 / MySQL 5.7, utf8.   mysql htbb_db < sql/sua_vong_quay.sql
--
-- May chu: real.VongQuay + com.htbb.pokemon.VongQuayLogic (luat), data.DatabaseVongQuay (CSDL). He cu
-- (Char.doXoso / doXosoLow / doXosoLuong, nin_xoso*) bo.
--
-- 1. Bang moi (may chu cung tu tao luc khoi dong):
--    tob_vong_quay_cuoc     cuoc dang cho cua luot hien tai (khong mat tien khi khoi dong lai)
--    tob_vong_quay_cho_nhan tien thang / hoan cho nguoi dang offline, cong luc dang nhap
--    tob_vong_quay_ngay     luot + tong cuoc / ngay / nhan vat, thiet bi + IP (tran ngay, chong clone)
--    tob_vong_quay_lich_su  moi luot da xong: hu, phi (ho hut), tra, nguoi thang - kiem "khong in tien"
-- 2. Danh muc cau hinh nhom vong_quay (giong het tools/cauhinh/danh_muc.json -> sql/pokemon_cau_hinh_trung_tam.sql;
--    chay tep do cung duoc). Lop co_dinh (giong thue / phi kinh te khac): may that dung mac dinh duoi day, doi
--    khan cap bang server.ini (vd vong_quay.vip.cuoc_toi_da=...), doi lau dai = sua danh_muc.json. Mac dinh:
--      thuong: cap 20, 1.000 - 10.000 xu / luot, 30.000 xu / ngay, 10 luot / ngay, 20 nguoi, phi 10%
--      VIP   : cap 50, 10.000 - 50.000 xu / luot, 100.000 xu / ngay, 10 luot / ngay, 20 nguoi, phi 10%
--      luong : cap 20, 10 - 100 luong / luot, 300 luong / ngay, 10 luot / ngay, 20 nguoi, phi 15%
--      luot 120 giay tinh tu nguoi dat dau tien, 10 giay cuoi khoa; chi 1 nguoi -> hoan du.
--    Cong chong clone (chong_clone.*: cap 20, tai khoan 24 gio, choi 10 gio, toi da 2 Pokemon / thiet bi / IP
--    / ngay) ap cho moi vong quay.
-- 3. Cuoc dang cho cua he cu (nin_xoso / nin_xoso_low = xu, nin_xoso_luong = luong, money > 0): may chu MOI hoan
--    tung dong qua tob_vong_quay_cho_nhan luc khoi dong (DatabaseVongQuay.chuyenCuocCu, idempotent) - tep nay
--    chi liet ke de doi chieu. Trien khai: dung may chu cu -> chay tep nay -> chay jar moi.

CREATE TABLE IF NOT EXISTS `tob_vong_quay_cuoc` (
  `loai` TINYINT NOT NULL, `charname` VARCHAR(40) NOT NULL, `char_id` INT NOT NULL DEFAULT 0,
  `so` BIGINT NOT NULL DEFAULT 0, `may` VARCHAR(64) NOT NULL DEFAULT '', `ip` VARCHAR(64) NOT NULL DEFAULT '',
  `luc` DATETIME NOT NULL, PRIMARY KEY (`loai`, `charname`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE IF NOT EXISTS `tob_vong_quay_cho_nhan` (
  `charname` VARCHAR(40) NOT NULL, `xu` BIGINT NOT NULL DEFAULT 0, `luong` BIGINT NOT NULL DEFAULT 0,
  `ly_do` VARCHAR(255) NOT NULL DEFAULT '', `cap_nhat` DATETIME NOT NULL, PRIMARY KEY (`charname`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE IF NOT EXISTS `tob_vong_quay_ngay` (
  `ngay` DATE NOT NULL, `loai` TINYINT NOT NULL, `charname` VARCHAR(40) NOT NULL,
  `may` VARCHAR(64) NOT NULL DEFAULT '', `ip` VARCHAR(64) NOT NULL DEFAULT '',
  `luot` INT NOT NULL DEFAULT 0, `tong` BIGINT NOT NULL DEFAULT 0, PRIMARY KEY (`ngay`, `loai`, `charname`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE IF NOT EXISTS `tob_vong_quay_lich_su` (
  `id` BIGINT NOT NULL AUTO_INCREMENT, `luc` DATETIME NOT NULL, `loai` TINYINT NOT NULL,
  `so_nguoi` INT NOT NULL DEFAULT 0, `hu` BIGINT NOT NULL DEFAULT 0, `phi` BIGINT NOT NULL DEFAULT 0,
  `tra` BIGINT NOT NULL DEFAULT 0, `hoan` TINYINT NOT NULL DEFAULT 0,
  `nguoi_thang` VARCHAR(40) NOT NULL DEFAULT '', `chi_tiet` VARCHAR(1000) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`), KEY `k_luc` (`luc`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- Danh muc (bang cau_hinh_nhom / cau_hinh_danh_muc do sql/pokemon_cau_hinh_trung_tam.sql tao; may chu game cung tu tao).
CREATE TABLE IF NOT EXISTS `cau_hinh_danh_muc` (`khoa` VARCHAR(64) NOT NULL, `nhom` VARCHAR(20) NOT NULL, `ten` VARCHAR(160) NOT NULL DEFAULT '', `mo_ta` TEXT NOT NULL, `kieu` VARCHAR(12) NOT NULL, `mac_dinh` VARCHAR(255) NOT NULL DEFAULT '', `gioi_han` TEXT NOT NULL, `ap_dung` VARCHAR(16) NOT NULL, `nhay` TINYINT NOT NULL DEFAULT 0, `khoa_prod` TINYINT NOT NULL DEFAULT 0, `chi_doc` TINYINT NOT NULL DEFAULT 0, `bang` VARCHAR(16) NOT NULL DEFAULT 'cau_hinh', `dung_o` VARCHAR(10) NOT NULL DEFAULT 'server', `nguon` VARCHAR(255) NOT NULL DEFAULT '', `thu_tu` INT NOT NULL DEFAULT 0, `lop` VARCHAR(10) NOT NULL DEFAULT 'chinh', `an` TINYINT NOT NULL DEFAULT 0, PRIMARY KEY (`khoa`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `cau_hinh_nhom` (`ma` VARCHAR(20) NOT NULL, `ten` VARCHAR(160) NOT NULL DEFAULT '', `mo_ta` TEXT NOT NULL, `thu_tu` INT NOT NULL DEFAULT 0, `an` TINYINT NOT NULL DEFAULT 0, PRIMARY KEY (`ma`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('vong_quay', 'Vòng quay may mắn (cố định)', 'Ba vòng quay góp hũ (thường / VIP bằng xu, lượng): người thắng nhận hũ trừ phí, phí là hố hút. Không in tiền: hũ = tổng cược; chỉ 1 người thì hoàn lại. Cổng chống clone áp như giao dịch xu (cấp, tuổi tài khoản, giờ chơi, tối đa N Pokémon cùng thiết bị / IP mỗi ngày). Mức cược, trần ngày, phí là công thức kinh tế cốt lõi: cố định (đổi khẩn cấp bằng server.ini).', 6, 1) ON DUPLICATE KEY UPDATE `ten`=VALUES(`ten`), `mo_ta`=VALUES(`mo_ta`), `thu_tu`=VALUES(`thu_tu`), `an`=VALUES(`an`);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('vong_quay.giay_moi_vong', 'vong_quay', 'Thời gian một lượt (giây)', 'Đếm từ lúc có người đặt đầu tiên. Hết giờ: từ 2 người trở lên thì quay, chỉ 1 người thì hoàn lại đủ.', 'so', '120', '{"min": 30, "max": 3600}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'com.htbb.pokemon.VongQuayLogic', 72, 'co_dinh', 1) ON DUPLICATE KEY UPDATE `nhom`=VALUES(`nhom`), `ten`=VALUES(`ten`), `mo_ta`=VALUES(`mo_ta`), `kieu`=VALUES(`kieu`), `mac_dinh`=VALUES(`mac_dinh`), `gioi_han`=VALUES(`gioi_han`), `ap_dung`=VALUES(`ap_dung`), `nhay`=VALUES(`nhay`), `khoa_prod`=VALUES(`khoa_prod`), `chi_doc`=VALUES(`chi_doc`), `bang`=VALUES(`bang`), `dung_o`=VALUES(`dung_o`), `nguon`=VALUES(`nguon`), `thu_tu`=VALUES(`thu_tu`), `lop`=VALUES(`lop`), `an`=VALUES(`an`);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('vong_quay.giay_khoa', 'vong_quay', 'Khoá đặt cuối lượt (giây)', 'Mấy giây cuối không nhận thêm cược.', 'so', '10', '{"min": 0, "max": 120}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'com.htbb.pokemon.VongQuayLogic', 73, 'co_dinh', 1) ON DUPLICATE KEY UPDATE `nhom`=VALUES(`nhom`), `ten`=VALUES(`ten`), `mo_ta`=VALUES(`mo_ta`), `kieu`=VALUES(`kieu`), `mac_dinh`=VALUES(`mac_dinh`), `gioi_han`=VALUES(`gioi_han`), `ap_dung`=VALUES(`ap_dung`), `nhay`=VALUES(`nhay`), `khoa_prod`=VALUES(`khoa_prod`), `chi_doc`=VALUES(`chi_doc`), `bang`=VALUES(`bang`), `dung_o`=VALUES(`dung_o`), `nguon`=VALUES(`nguon`), `thu_tu`=VALUES(`thu_tu`), `lop`=VALUES(`lop`), `an`=VALUES(`an`);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('vong_quay.thuong.bat', 'vong_quay', 'Vòng quay thường: bật', '0 = đóng (người đang chờ vẫn được quay / hoàn như thường).', 'co', '1', '{}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.VongQuay', 74, 'co_dinh', 1) ON DUPLICATE KEY UPDATE `nhom`=VALUES(`nhom`), `ten`=VALUES(`ten`), `mo_ta`=VALUES(`mo_ta`), `kieu`=VALUES(`kieu`), `mac_dinh`=VALUES(`mac_dinh`), `gioi_han`=VALUES(`gioi_han`), `ap_dung`=VALUES(`ap_dung`), `nhay`=VALUES(`nhay`), `khoa_prod`=VALUES(`khoa_prod`), `chi_doc`=VALUES(`chi_doc`), `bang`=VALUES(`bang`), `dung_o`=VALUES(`dung_o`), `nguon`=VALUES(`nguon`), `thu_tu`=VALUES(`thu_tu`), `lop`=VALUES(`lop`), `an`=VALUES(`an`);
