-- Doi chieu: cuoc dang cho cua he cu (may chu moi se hoan luc khoi dong).
SELECT 'nin_xoso' AS bang, COUNT(*) AS so_dong, COALESCE(SUM(money), 0) AS tong FROM `nin_xoso` WHERE money > 0;
SELECT 'nin_xoso_low' AS bang, COUNT(*) AS so_dong, COALESCE(SUM(money), 0) AS tong FROM `nin_xoso_low` WHERE money > 0;
